import unittest
from service import normalize_name


class PublicTests(unittest.TestCase):
    def test_trim(self):
        self.assertEqual(normalize_name(" alice "), "alice")

    def test_unicode_canonical(self):
        self.assertEqual(normalize_name(" Straße "), "strasse")
